from .api_base import API_base 

class Video_schedule_conference(API_base):
    """
    Schedule a video conference with multiple participants and set up reminders.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_conference_details"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        p_conference_details = params.get('p_conference_details', None)
        if p_conference_details is not None:
            is_valid, error = self.validate_type(p_conference_details, 'p_conference_details', dict)
            if not is_valid:
                return error
        
        if p_conference_details is not None:

            p_title = p_conference_details.get('p_title', None)
            if p_title is None:
                return self.handle_error(f"Required parameter 'p_title' is missing", 400)
            is_valid, error = self.validate_type(p_title, 'p_title', str)
            if not is_valid:
                return error
            
            p_start_time = p_conference_details.get('p_start_time', None)
            if p_start_time is None:
                return self.handle_error(f"Required parameter 'p_start_time' is missing", 400)
            is_valid, error = self.validate_type(p_start_time, 'p_start_time', str)
            if not is_valid:
                return error
            
            if p_start_time is not None and p_start_time not in ["09:00", "12:00", "15:00", "18:00"]:
                return self.handle_error(f"Parameter 'p_start_time' not in valid enum", 400)
            
            p_duration = p_conference_details.get('p_duration', None)
            if p_duration is None:
                return self.handle_error(f"Required parameter 'p_duration' is missing", 400)
            is_valid, error = self.validate_type(p_duration, 'p_duration', int)
            if not is_valid:
                return error
            
            p_participants = p_conference_details.get('p_participants', None)
            if p_participants is None:
                return self.handle_error(f"Required parameter 'p_participants' is missing", 400)
            is_valid, error = self.validate_type(p_participants, 'p_participants', list)
            if not is_valid:
                return error
            
            p_reminders = p_conference_details.get('p_reminders', None)
            if p_reminders is not None:
                is_valid, error = self.validate_type(p_reminders, 'p_reminders', list)
                if not is_valid:
                    return error
            
        return {
            "status_code": 200, 
            "results": {
                "function_name": "Video_schedule_conference",
                "p_conference_details": p_conference_details
            }
        }

